using System.Collections.Generic;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "RandomizedButtonCustomEventSetup", menuName = "Data/BattleSceneSetups/Events/RandomizedButtonCustomEventSetup", order = 0)]
public class RandomizedButtonCustomEventSetup : ButtonCustomEventSetup
{
	[SerializeField]
	private int randomButtonAmountToPick;

	[SerializeField]
	private EventButtonData[] fixedEventButtonDatas;

	[SerializeField]
	private MapHandler mapHandler;

	[SerializeField]
	private bool dustyAmphitheater;

	[SerializeField]
	private bool ancestralForge;

	[SerializeField]
	[ShowIf("dustyAmphitheaterOrAncestralForge")]
	private EventButtonData skipButton;

	private bool dustyAmphitheaterOrAncestralForge
	{
		get
		{
			if (!dustyAmphitheater)
			{
				return ancestralForge;
			}
			return true;
		}
	}

	public override EventButtonData[] GetEventButtonDatas()
	{
		RandomUtilities.SetUnityEngineRandomInitStateSeed(mapHandler.GetSeedWithCurrentMapPlayerTracker());
		List<EventButtonData> list = eventButtonDatas.DuplicateAsList();
		List<EventButtonData> list2 = new List<EventButtonData>();
		EventButtonData[] array;
		if (dustyAmphitheater)
		{
			int i;
			for (i = 0; i < ReferenceSingleton<AssetsReference>.Instance.PlayerCurrentOmens.RuntimeOmens.Count; i++)
			{
				list.RemoveAll(delegate(EventButtonData eventButton)
				{
					OmenData omenData2 = (eventButton.eventAction as DustyAmphitheaterOmenDataEventAction).OmenData;
					return ReferenceSingleton<AssetsReference>.Instance.PlayerCurrentOmens.RuntimeOmens[i].OmenData == omenData2;
				});
			}
			for (int num = list.Count - 1; num >= 0; num--)
			{
				OmenData omenData = (list[num].eventAction as DustyAmphitheaterOmenDataEventAction).OmenData;
				if (omenData is OnNewRuneOmenData)
				{
					OnNewRuneOmenData onNewRuneOmenData = omenData as OnNewRuneOmenData;
					if (!onNewRuneOmenData.AddRune && !onNewRuneOmenData.ReplaceAllRunes)
					{
						if (onNewRuneOmenData.GetSpecificRuneIndex() == -1)
						{
							list.Remove(list[num]);
						}
					}
					else if (onNewRuneOmenData.AddRune && onNewRuneOmenData.GetEmptyIndex() == -1)
					{
						list.Remove(list[num]);
					}
				}
			}
			if (list.Count == 0)
			{
				return new EventButtonData[1] { skipButton };
			}
			list2 = list.PickRandom(randomButtonAmountToPick);
			array = new EventButtonData[Mathf.Min(list.Count, randomButtonAmountToPick)];
		}
		else
		{
			if (ancestralForge && ReferenceSingleton<AssetsReference>.Instance.DicePool.GetDicesAmount() == 0)
			{
				return new EventButtonData[1] { skipButton };
			}
			array = new EventButtonData[randomButtonAmountToPick + fixedEventButtonDatas.Length];
			list2 = eventButtonDatas.DuplicateAsList().PickRandom(randomButtonAmountToPick);
		}
		for (int j = 0; j < list2.Count; j++)
		{
			array[j] = list2[j];
		}
		for (int k = 0; k < fixedEventButtonDatas.Length; k++)
		{
			array[k + list2.Count] = fixedEventButtonDatas[k];
		}
		return array;
	}
}
